// Arkon Store Sync - what kind of run this is.
// Three ways in: a caller workflow (the Steering Cell after it appended an
// incident, the transition endpoint after it appended a move), the webhook for a
// person or a script, and the command line. Only the webhook can ask for a
// rebuild, and the source is recorded on the sync line.
const first = $input.first().json ?? {};
const isWebhook = first.headers !== undefined && (first.body !== undefined || first.query !== undefined);
const body = isWebhook ? (first.body && typeof first.body === "object" ? first.body : {}) : first;
const rebuild = ["1", "true", "yes"].includes(String(body.rebuild ?? "").toLowerCase());
const source = isWebhook ? "webhook" : String(first.source ?? "").trim() || "command_line";
return [{ json: { rebuild, source } }];

// Arkon Store Sync - fold both logs, then decide which rows to write.
// The incident line is written once, at new, and never rewritten; the current
// status of an incident is the fold of the transition log onto that line
// (charter 7.2). This node folds every incident, computes the store summary
// from all of them, and emits rows only for what the last sync had not seen:
// new incident lines, and every incident a new transition line touched. On a
// rebuild, or when no summary row exists yet, everything is a row.
const LIFECYCLE = ["new", "acknowledged", "in_containment", "resolved", "closed", "false_positive"];
const OPEN_STATUSES = ["new", "acknowledged", "in_containment"];
const TERMINAL_STATUSES = ["closed", "false_positive"];
const REQUESTABLE_STATUSES = ["acknowledged", "in_containment", "resolved", "closed", "false_positive"];
const ALLOWED_TRANSITIONS = {"new": ["acknowledged", "false_positive"], "acknowledged": ["in_containment", "resolved", "false_positive"], "in_containment": ["resolved", "false_positive"], "resolved": ["closed", "in_containment", "false_positive"], "closed": [], "false_positive": []};
const ACK_WINDOW_MINUTES = {"P1": 15, "P2": 60};
// Apply the transition log to one incident. The incident line in the store is
// written once, at new, and never rewritten; the current status is therefore the
// last transition recorded against it, and the KPI timestamps are the first time
// each milestone was reached. Charter 7.2.
function arkonFold(incident, transitionsById) {
  const list = (transitionsById[incident.incident_id] ?? [])
    .slice()
    .sort((a, b) => String(a.recorded_at ?? "").localeCompare(String(b.recorded_at ?? "")));

  const stored = String(incident.status ?? "new").toLowerCase();
  const current = list.length ? String(list[list.length - 1].to_status).toLowerCase() : stored;

  const firstAt = (status) => {
    const hit = list.find((t) => String(t.to_status).toLowerCase() === status);
    return hit ? hit.recorded_at : null;
  };

  const created = Date.parse(incident.created_at ?? "");
  const minutesFromCreated = (iso) => {
    if (!iso || Number.isNaN(created)) return null;
    const at = Date.parse(iso);
    return Number.isNaN(at) ? null : Math.round(((at - created) / 60000) * 10) / 10;
  };

  const acknowledgedAt = firstAt("acknowledged");
  const resolvedAt = firstAt("resolved");
  // A false_positive is a closing outcome: the incident is finished with, and a
  // response time that counted only "closed" would silently drop those cases.
  const closedAt = firstAt("closed") ?? firstAt("false_positive");

  return {
    status: current,
    stored_status: stored,
    transition_count: list.length,
    is_terminal: TERMINAL_STATUSES.includes(current),
    acknowledged_at: acknowledgedAt,
    resolved_at: resolvedAt,
    closed_at: closedAt,
    minutes_to_acknowledge: minutesFromCreated(acknowledgedAt),
    minutes_to_resolve: minutesFromCreated(resolvedAt),
    minutes_to_close: minutesFromCreated(closedAt),
    history: list.map((t) => ({
      transition_id: t.transition_id ?? null,
      recorded_at: t.recorded_at ?? null,
      from_status: t.from_status ?? null,
      to_status: t.to_status ?? null,
      actor: t.actor ?? null,
      note: t.note ?? null,
    })),
  };
}

// Parse a JSONL store into transitions grouped by incident id. Damaged lines are
// counted rather than thrown: one bad line must not take the whole lifecycle out.
function arkonTransitionsById(text) {
  const byId = {};
  let unreadable = 0;
  for (const line of String(text ?? "").split("\n").map((l) => l.trim()).filter(Boolean)) {
    try {
      const record = JSON.parse(line);
      const id = String(record.incident_id ?? "");
      if (!id) {
        unreadable += 1;
        continue;
      }
      (byId[id] = byId[id] ?? []).push(record);
    } catch (error) {
      unreadable += 1;
    }
  }
  return { byId, unreadable };
}

// A CMAPSS record id is FD<digits>-Unit-<token>. Only these carry an engine unit;
// SCANIA-APS-000056 is a service record and has none, and reporting its last
// token as a "unit" is how a field that reads fine comes to mean nothing.
const CMAPSS_RECORD = /^FD\d+-Unit-.+$/i;
const arkonRecordId = (incident) => String(incident.event?.evidence?.record_id ?? "");
const arkonUnitToken = (incident) => {
  const recordId = arkonRecordId(incident);
  return CMAPSS_RECORD.test(recordId) ? recordId.split("-").pop() : null;
};

// The flat projection of one incident line with its fold applied. Every field the
// status API serves per incident except the two clock-dependent ones.
function arkonProject(incident, life) {
  const recordId = arkonRecordId(incident);
  const isCmapss = CMAPSS_RECORD.test(recordId);
  return {
    incident_id: incident.incident_id,
    created_at: incident.created_at ?? null,
    priority: incident.priority ?? null,
    status: life.status,
    raised_as: life.stored_status,
    is_terminal: life.is_terminal,
    transition_count: life.transition_count,
    acknowledged_at: life.acknowledged_at,
    resolved_at: life.resolved_at,
    closed_at: life.closed_at,
    minutes_to_acknowledge: life.minutes_to_acknowledge,
    minutes_to_resolve: life.minutes_to_resolve,
    minutes_to_close: life.minutes_to_close,
    acknowledge_due_minutes: ACK_WINDOW_MINUTES[String(incident.priority ?? "").toUpperCase()] ?? null,
    unit: arkonUnitToken(incident),
    record_id: recordId || null,
    summary: incident.summary ?? null,
    recommended_action: incident.recommended_action ?? null,
    source_module: incident.source_module ?? null,
    business_domain: incident.business_domain ?? null,
    assigned_to: incident.assigned_to ?? null,
    assigned_role: incident.assigned_role ?? null,
    escalation_contact: incident.escalation_contact ?? null,
    event_id: incident.event?.event_id ?? null,
    risk_score: incident.event?.risk_score ?? null,
    evidence: incident.event?.evidence ?? null,
    // predicted_rul is a CMAPSS word and only a CMAPSS record has one; served
    // from evidence.prediction for every module it once turned a Scania failure
    // probability into a remaining useful life of 0.0373 cycles.
    predicted_rul: isCmapss ? (incident.event?.evidence?.prediction ?? null) : null,
    priority_threshold: isCmapss ? (incident.event?.evidence?.threshold ?? null) : null,
    model_version: incident.event?.evidence?.model_version ?? null,
    data_origin: incident.event?.context_origin ?? null,
    operational_context_origin: incident.event?.operational_context?.context_origin ?? null,
    history: life.history,
  };
}
const INCIDENT_COLUMNS = ["incident_id", "created_at", "priority", "status", "raised_as", "is_terminal", "transition_count", "acknowledged_at", "resolved_at", "closed_at", "minutes_to_acknowledge", "minutes_to_resolve", "minutes_to_close", "acknowledge_due_minutes", "unit", "record_id", "summary", "recommended_action", "source_module", "business_domain", "assigned_to", "assigned_role", "escalation_contact", "event_id", "risk_score", "evidence_json", "predicted_rul", "priority_threshold", "model_version", "data_origin", "operational_context_origin", "history_json", "store_line", "synced_at"];
const TRANSITION_COLUMNS = ["transition_id", "recorded_at", "incident_id", "incident_priority", "incident_created_at", "from_status", "to_status", "actor", "note", "minutes_since_created", "minutes_since_previous_transition", "acknowledge_window_minutes", "acknowledged_within_window", "context_origin", "log_line", "synced_at"];
const SUMMARY_COLUMNS = ["key", "synced_at", "sync_mode", "sync_source", "duration_ms", "incidents_lines", "transitions_lines", "incidents_unreadable", "transitions_unreadable", "total_incidents", "open_incidents", "overdue_incidents", "incidents_by_priority_json", "incidents_by_status_json", "total_transitions", "incidents_with_transitions", "response_times_json", "incident_rows_written", "transition_rows_written", "highest_incident_id", "highest_transition_id"];
const request = $("Read Request").first().json;
const storeText = $("Extract Store Text").first().json.store_text ?? "";
const transitionsText = $("Extract Transitions Text").first().json.transitions_text ?? "";
const summaryRows = $("Get Summary").all().map((item) => item.json).filter((row) => row && row.key === "store");
const previous = request.rebuild || !summaryRows.length ? null : summaryRows[0];
const started = Date.now();
const now = new Date();
const syncedAt = now.toISOString();

// Every non-empty line gets an ordinal, readable or not: the summary records how
// many lines the sync had seen, and the next sync starts after that many.
const incidents = [];
let incidentLines = 0;
let incidentsUnreadable = 0;
for (const raw of storeText.split("\n")) {
  const line = raw.trim();
  if (!line) continue;
  incidentLines += 1;
  try {
    const incident = JSON.parse(line);
    if (!incident || typeof incident !== "object" || !incident.incident_id) {
      incidentsUnreadable += 1;
      continue;
    }
    incidents.push({ incident, line: incidentLines });
  } catch (error) {
    incidentsUnreadable += 1;
  }
}

// The same parse for transitions, grouped by incident for the fold and kept in
// log order for the rows. The rule for a damaged line is the fold's own: count
// it, never throw, because one bad line must not take the lifecycle out.
const transitionsById = {};
const transitionRecords = [];
let transitionLines = 0;
let transitionsUnreadable = 0;
for (const raw of transitionsText.split("\n")) {
  const line = raw.trim();
  if (!line) continue;
  transitionLines += 1;
  try {
    const record = JSON.parse(line);
    const id = String(record?.incident_id ?? "");
    if (!id) {
      transitionsUnreadable += 1;
      continue;
    }
    (transitionsById[id] = transitionsById[id] ?? []).push(record);
    transitionRecords.push({ record, line: transitionLines });
  } catch (error) {
    transitionsUnreadable += 1;
  }
}

const folded = incidents.map((entry) => ({ ...entry, life: arkonFold(entry.incident, transitionsById) }));
const statusOf = (entry) => entry.life.status;

// What to write. Without a previous summary every row is new.
const prevIncidentLines = previous ? Number(previous.incidents_lines ?? 0) : 0;
const prevTransitionLines = previous ? Number(previous.transitions_lines ?? 0) : 0;
const touched = new Set();
for (const { record, line } of transitionRecords) {
  if (line > prevTransitionLines) touched.add(String(record.incident_id));
}
const changed = folded.filter(
  (entry) => !previous || entry.line > prevIncidentLines || touched.has(String(entry.incident.incident_id))
);
const newTransitions = transitionRecords.filter((entry) => !previous || entry.line > prevTransitionLines);

// A data table row holds strings, numbers, booleans and nulls. Anything nested
// travels as JSON text and is decoded again by the status API.
const flat = (value) => {
  if (value === null || value === undefined) return null;
  if (typeof value === "object") return JSON.stringify(value);
  return value;
};

const incidentRow = ({ incident, line, life }) => {
  const projected = arkonProject(incident, life);
  const row = {};
  for (const column of INCIDENT_COLUMNS) {
    if (column === "evidence_json") row[column] = projected.evidence === null ? null : JSON.stringify(projected.evidence);
    else if (column === "history_json") row[column] = JSON.stringify(projected.history ?? []);
    else if (column === "store_line") row[column] = line;
    else if (column === "synced_at") row[column] = syncedAt;
    else row[column] = flat(projected[column]);
  }
  return row;
};

const transitionRow = ({ record, line }) => {
  const row = {};
  for (const column of TRANSITION_COLUMNS) {
    if (column === "log_line") row[column] = line;
    else if (column === "synced_at") row[column] = syncedAt;
    else row[column] = flat(record[column]);
  }
  return row;
};

// The store summary, computed over every incident exactly as the status API
// computed it before the move, so the numbers a consumer sees do not change
// with the storage.
const byPriority = {};
const byStatus = {};
for (const entry of folded) {
  const key = String(entry.incident.priority ?? "unknown").toUpperCase();
  byPriority[key] = (byPriority[key] ?? 0) + 1;
  const state = statusOf(entry);
  byStatus[state] = (byStatus[state] ?? 0) + 1;
}

const ageMinutes = (incident) => {
  const created = Date.parse(incident.created_at ?? "");
  return Number.isNaN(created) ? null : Math.round((now.getTime() - created) / 60000);
};
const isOverdue = (entry) => {
  const window = ACK_WINDOW_MINUTES[String(entry.incident.priority ?? "").toUpperCase()];
  if (window === undefined) return false;
  if (statusOf(entry) !== "new") return false;
  const age = ageMinutes(entry.incident);
  return age !== null && age > window;
};

// The median rather than the mean, because one incident acknowledged the next
// morning would otherwise move the number more than every one acknowledged on
// time (charter 7.2).
const median = (values) => {
  const sorted = values.filter((v) => v !== null && v !== undefined).sort((a, b) => a - b);
  if (!sorted.length) return null;
  const middle = Math.floor(sorted.length / 2);
  const value = sorted.length % 2 ? sorted[middle] : (sorted[middle - 1] + sorted[middle]) / 2;
  return Math.round(value * 10) / 10;
};
const ackMinutes = [];
const closeMinutes = [];
let acknowledgedInWindow = 0;
let acknowledgedLate = 0;
for (const entry of folded) {
  const life = entry.life;
  if (life.minutes_to_acknowledge !== null) {
    ackMinutes.push(life.minutes_to_acknowledge);
    const window = ACK_WINDOW_MINUTES[String(entry.incident.priority ?? "").toUpperCase()];
    if (window !== undefined) {
      if (life.minutes_to_acknowledge <= window) acknowledgedInWindow += 1;
      else acknowledgedLate += 1;
    }
  }
  if (life.minutes_to_close !== null) closeMinutes.push(life.minutes_to_close);
}

const highest = (values) => values.reduce((best, value) => (best === null || String(value) > best ? String(value) : best), null);

const summaryRow = {
  key: "store",
  synced_at: syncedAt,
  sync_mode: request.rebuild ? "rebuild" : previous ? "incremental" : "initial",
  sync_source: request.source,
  duration_ms: Date.now() - started,
  incidents_lines: incidentLines,
  transitions_lines: transitionLines,
  incidents_unreadable: incidentsUnreadable,
  transitions_unreadable: transitionsUnreadable,
  total_incidents: folded.length,
  open_incidents: folded.filter((entry) => OPEN_STATUSES.includes(statusOf(entry))).length,
  overdue_incidents: folded.filter(isOverdue).length,
  incidents_by_priority_json: JSON.stringify(byPriority),
  incidents_by_status_json: JSON.stringify(byStatus),
  total_transitions: transitionRecords.length,
  incidents_with_transitions: Object.keys(transitionsById).length,
  response_times_json: JSON.stringify({
    acknowledged_incidents: ackMinutes.length,
    median_minutes_to_acknowledge: median(ackMinutes),
    acknowledged_within_window: acknowledgedInWindow,
    acknowledged_late: acknowledgedLate,
    closed_incidents: closeMinutes.length,
    median_minutes_to_close: median(closeMinutes),
  }),
  incident_rows_written: changed.length,
  transition_rows_written: newTransitions.length,
  highest_incident_id: highest(folded.map((entry) => entry.incident.incident_id)),
  highest_transition_id: highest(transitionRecords.map((entry) => entry.record.transition_id ?? "")),
};
for (const column of SUMMARY_COLUMNS) {
  if (!(column in summaryRow)) summaryRow[column] = null;
}

return [
  {
    json: {
      request,
      summary_row: summaryRow,
      incident_rows: changed.map(incidentRow),
      transition_rows: newTransitions.map(transitionRow),
    },
  },
];

// The one summary row, rewritten by every sync. Always exactly one item, which
// is why this branch carries the sync line and the webhook's answer.
return [{ json: $("Fold Store").first().json.summary_row }];

// The sync's own record, one line per run: the summary numbers and the row
// counts. Successful executions are not stored (workflow settings), so this
// line is the evidence that a sync happened and what it found.
const summary = $("Fold Store").first().json.summary_row;
return [{ json: { ...summary, sync_jsonl: JSON.stringify(summary) + "\n" } }];
